<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>可衣 KEEWEAR - 上海优质女装 | 日常与职场</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; color: #2c2c2c; background: #fff; line-height: 1.6; }
        a { text-decoration: none; color: inherit; }
        img { max-width: 100%; display: block; }

        /* Header */
        .top-bar { background: #2c2c2c; color: #fff; font-size: 12px; padding: 6px 0; text-align: center; }
        .top-bar span { margin: 0 15px; }
        .header { background: #fff; border-bottom: 1px solid #eee; position: sticky; top: 0; z-index: 1000; }
        .header-inner { max-width: 1440px; margin: 0 auto; padding: 16px 40px; display: flex; align-items: center; justify-content: space-between; }
        .logo { font-size: 28px; font-weight: 700; letter-spacing: 4px; color: #2c2c2c; }
        .logo span { color: #b8860b; }
        .nav { display: flex; gap: 32px; }
        .nav a { font-size: 15px; color: #555; padding: 8px 0; border-bottom: 2px solid transparent; transition: all .3s; }
        .nav a:hover, .nav a.active { color: #2c2c2c; border-bottom-color: #b8860b; }
        .header-actions { display: flex; align-items: center; gap: 20px; }
        .search-box { display: flex; align-items: center; background: #f5f5f5; border-radius: 20px; padding: 6px 14px; }
        .search-box input { border: none; background: none; outline: none; font-size: 13px; width: 140px; }
        .search-box svg { margin-right: 8px; opacity: .4; }
        .cart-icon { position: relative; cursor: pointer; }
        .cart-icon .badge { position: absolute; top: -6px; right: -6px; background: #c0392b; color: #fff; font-size: 10px; width: 16px; height: 16px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }

        /* Hero */
        .hero { position: relative; height: 520px; overflow: hidden; background: linear-gradient(135deg, #f5ede6 0%, #e8ddd3 50%, #d4c5b5 100%); display: flex; align-items: center; }
        .hero-content { max-width: 1440px; margin: 0 auto; padding: 0 40px; width: 100%; }
        .hero-tag { display: inline-block; background: #b8860b; color: #fff; font-size: 12px; padding: 4px 12px; border-radius: 3px; margin-bottom: 20px; letter-spacing: 2px; }
        .hero h1 { font-size: 48px; font-weight: 300; color: #2c2c2c; margin-bottom: 16px; line-height: 1.3; }
        .hero p { font-size: 16px; color: #666; max-width: 480px; margin-bottom: 32px; }
        .hero-btn { display: inline-block; background: #2c2c2c; color: #fff; padding: 14px 36px; font-size: 14px; letter-spacing: 2px; transition: all .3s; }
        .hero-btn:hover { background: #b8860b; }
        .hero-visual { position: absolute; right: 40px; top: 50%; transform: translateY(-50%); width: 400px; height: 420px; background: linear-gradient(180deg, #e8d5c4 0%, #c9a88c 100%); border-radius: 8px 8px 200px 200px; box-shadow: 30px 30px 60px rgba(0,0,0,.1); }
        .hero-visual::after { content: ''; position: absolute; bottom: 60px; left: 50%; transform: translateX(-50%); width: 80px; height: 80px; background: #fff; border-radius: 50%; opacity: .3; }

        /* Sections */
        .section { max-width: 1440px; margin: 0 auto; padding: 80px 40px; }
        .section-title { text-align: center; margin-bottom: 48px; }
        .section-title h2 { font-size: 28px; font-weight: 400; color: #2c2c2c; margin-bottom: 8px; }
        .section-title p { font-size: 14px; color: #999; }
        .section-title .line { width: 40px; height: 2px; background: #b8860b; margin: 16px auto 0; }

        /* Categories */
        .cat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
        .cat-item { position: relative; height: 280px; overflow: hidden; cursor: pointer; }
        .cat-item .cat-bg { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; transition: transform .4s; }
        .cat-item:hover .cat-bg { transform: scale(1.05); }
        .cat-item .cat-label { position: absolute; bottom: 24px; left: 24px; color: #fff; font-size: 18px; font-weight: 500; text-shadow: 0 1px 4px rgba(0,0,0,.3); }
        .cat-item .cat-label small { display: block; font-size: 12px; opacity: .8; margin-top: 4px; }
        .cat-bg-1 { background: linear-gradient(160deg, #d4a574, #b8860b); }
        .cat-bg-2 { background: linear-gradient(160deg, #8b9dc3, #5c6f91); }
        .cat-bg-3 { background: linear-gradient(160deg, #c9a0a0, #a06c6c); }
        .cat-bg-4 { background: linear-gradient(160deg, #7ba88e, #4a7c62); }

        /* Products */
        .product-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 28px; }
        .product-card { cursor: pointer; transition: box-shadow .3s; }
        .product-card:hover { box-shadow: 0 8px 30px rgba(0,0,0,.08); }
        .product-img { height: 320px; border-radius: 4px; overflow: hidden; margin-bottom: 16px; }
        .product-img .img-inner { width: 100%; height: 100%; transition: transform .4s; }
        .product-card:hover .img-inner { transform: scale(1.03); }
        .product-info { padding: 0 4px; }
        .product-info h3 { font-size: 15px; font-weight: 500; color: #2c2c2c; margin-bottom: 6px; }
        .product-info .price { font-size: 16px; color: #c0392b; font-weight: 600; }
        .product-info .price .original { font-size: 12px; color: #aaa; text-decoration: line-through; margin-left: 8px; }
        .product-info .tag { display: inline-block; font-size: 11px; background: #fff3e0; color: #b8860b; padding: 2px 8px; border-radius: 2px; margin-top: 6px; }

        /* Brand Story */
        .brand-story { background: #f9f6f3; }
        .brand-inner { display: flex; align-items: center; gap: 60px; max-width: 1100px; margin: 0 auto; }
        .brand-visual { width: 380px; height: 460px; background: linear-gradient(180deg, #e6d5c3, #c9a88c); border-radius: 200px 200px 4px 4px; flex-shrink: 0; }
        .brand-text h3 { font-size: 24px; font-weight: 400; margin-bottom: 20px; color: #2c2c2c; }
        .brand-text p { font-size: 14px; color: #666; line-height: 2; margin-bottom: 16px; }
        .brand-text .brand-link { display: inline-block; margin-top: 20px; font-size: 14px; color: #b8860b; border-bottom: 1px solid #b8860b; padding-bottom: 2px; }

        /* Testimonials */
        .testi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
        .testi-card { background: #fafafa; padding: 32px; border-radius: 4px; }
        .testi-stars { color: #b8860b; font-size: 14px; margin-bottom: 16px; }
        .testi-card p { font-size: 14px; color: #555; line-height: 1.8; margin-bottom: 20px; }
        .testi-author { font-size: 13px; color: #999; }
        .testi-author strong { color: #2c2c2c; display: block; margin-bottom: 2px; font-size: 14px; }

        /* Footer */
        .footer { background: #2c2c2c; color: #aaa; padding: 60px 40px 30px; }
        .footer-inner { max-width: 1440px; margin: 0 auto; display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; padding-bottom: 40px; border-bottom: 1px solid #444; }
        .footer h4 { color: #fff; font-size: 15px; margin-bottom: 16px; font-weight: 500; }
        .footer p, .footer a { font-size: 13px; line-height: 2.2; color: #999; }
        .footer a:hover { color: #fff; }
        .footer-bottom { max-width: 1440px; margin: 0 auto; padding-top: 24px; font-size: 12px; text-align: center; color: #666; }

        /* Newsletter */
        .newsletter { background: #f5ede6; text-align: center; padding: 50px 40px; }
        .newsletter h3 { font-size: 20px; font-weight: 400; margin-bottom: 12px; }
        .newsletter p { font-size: 13px; color: #888; margin-bottom: 24px; }
        .newsletter-form { display: flex; max-width: 400px; margin: 0 auto; }
        .newsletter-form input { flex: 1; padding: 12px 16px; border: 1px solid #ddd; border-right: none; outline: none; font-size: 13px; }
        .newsletter-form button { padding: 12px 24px; background: #2c2c2c; color: #fff; border: none; font-size: 13px; cursor: pointer; }
        .newsletter-form button:hover { background: #b8860b; }

        @media (max-width: 1024px) {
            .hero-visual { display: none; }
            .cat-grid, .product-grid { grid-template-columns: repeat(2, 1fr); }
            .testi-grid { grid-template-columns: 1fr; }
            .brand-inner { flex-direction: column; }
            .brand-visual { width: 100%; height: 300px; }
            .footer-inner { grid-template-columns: 1fr 1fr; }
        }
        @media (max-width: 768px) {
            .hero { height: 400px; }
            .hero h1 { font-size: 32px; }
            .nav { display: none; }
            .cat-grid, .product-grid { grid-template-columns: 1fr; }
            .section { padding: 50px 20px; }
            .header-inner { padding: 14px 20px; }
        }
    </style>
</head>
