    <script>
        // Remove item
        document.querySelectorAll('.c-remove').forEach(btn => {
            btn.addEventListener('click', function() {
                const item = this.closest('.cart-item');
                item.style.opacity = '0';
                item.style.transform = 'translateX(20px)';
                item.style.transition = 'all .3s';
                setTimeout(() => {
                    item.remove();
                    updateCart();
                }, 300);
            });
        });

        // Quantity
        document.querySelectorAll('.qty-ctrl button').forEach(btn => {
            btn.addEventListener('click', function() {
                const input = this.nextElementSibling;
                let val = parseInt(input.value);
                if (this.textContent === '+') {
                    if (val < 10) input.value = val + 1;
                } else {
                    if (val > 1) input.value = val - 1;
                }
                updateCart();
            });
        });

        function updateCart() {
            const items = document.querySelectorAll('.cart-item');
            const badge = document.querySelector('.cart-icon .badge');
            let total = 0;
            items.forEach(item => {
                const price = parseFloat(item.querySelector('.c-price').textContent.replace(/[¥,]/g, '').trim().split(/\s+/).pop());
                const qty = parseInt(item.querySelector('.qty-ctrl input').value);
                total += price * qty;
            });
            badge.textContent = items.length;
            const header = document.querySelector('.cart-header span');
            if (header) header.textContent = '共 ' + items.length + ' 件商品';

            if (items.length === 0) {
                document.querySelector('.cart-layout').style.display = 'none';
                document.getElementById('cartEmpty').style.display = 'block';
            }
        }
    </script>
